  ('WB', 2011, '{"parties":["TMC","INC"],"source":"https://en.wikipedia.org/wiki/2011_West_Bengal_Legislative_Assembly_election"}'::jsonb),
  ('WB', 2016, '{"parties":["TMC"],"source":"https://en.wikipedia.org/wiki/2016_West_Bengal_Legislative_Assembly_election"}'::jsonb),
  ('WB', 2021, '{"parties":["TMC"],"source":"https://en.wikipedia.org/wiki/2021_West_Bengal_Legislative_Assembly_election"}'::jsonb),
  ('WB', 2026, '{"parties":["BJP"],"source":"https://en.wikipedia.org/wiki/2026_West_Bengal_Legislative_Assembly_election"}'::jsonb)
) AS g(code, year, gov)
JOIN states s ON s.code = g.code
WHERE e.state_id = s.id AND e.year = g.year AND e.type = 'VS' AND e.manifest_draft IS NOT NULL
  AND NOT (e.manifest_draft ? 'government');
